await p.evaluate(()=>{const j=DEUTSCH_JOURNEY,a=DEUTSCH_ADAPTIVE;j.open(0,true);document.querySelector('#alContinue').click();while(!a.snapshot().finished){const q=a.snapshot().queue[a.snapshot().index];a.answer(q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(!document.querySelector('[data-team-final="true"][data-team-state="success"]')||!document.querySelector('[data-compass-awake]')||!document.querySelector('#journeyNext').textContent.includes('Вирушити до мешканців'))throw Error('Missing compass finale/continuation');});await loaded();await p.clock.runFor(2100);await p.screenshot({path:'audit-screenshots/team-compass-finale.png',fullPage:true});await p.click('#journeyNext');if(!await p.evaluate(()=>DEUTSCH_JOURNEY.island===1))throw Error('Final button did not reach second island');
